export function assertSceneIdentityEvidence(e:Anchor,units:readonly ImportUnit[],memberships:readonly SceneIdentityMembership[],targetId?:string):void{const range=anchorRange(e,unitsMap(units));if(!memberships.some(m=>{if(targetId!==undefined&&m.identityId!==targetId)return false;let covered=range.start;for(const r of m.ownedRanges.filter(r=>r.unitId===range.unitId&&r.unitHash===range.unitHash).sort((a,b)=>a.start-b.start)){if(r.end<=covered)continue;if(r.start>covered)return false;covered=Math.max(covered,r.end);if(covered>=range.end)return true}return false}))fail('anchor')}

